<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Sorting Visualizer</title>
    <style>
        /* Dark Theme & Base Styles */
        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            background: #0f0f1a;
            color: #e0e0e0;
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            margin: 0;
            padding: 20px;
        }

        #app {
            width: 100%;
            max-width: 960px;
            background: #1a1a2e;
            border-radius: 16px;
            padding: 30px 30px 40px;
            box-shadow: 0 20px 40px rgba(0, 0, 0, 0.6);
            border: 1px solid #2a2a40;
        }

        h1 {
            text-align: center;
            font-weight: 400;
            font-size: 1.8rem;
            letter-spacing: 1px;
            margin-bottom: 20px;
            color: #c0c0e0;
        }

        #controls {
            display: flex;
            justify-content: center;
            gap: 15px;
            flex-wrap: wrap;
            margin-bottom: 25px;
        }

        button {
            background: #2a2a40;
            color: #e0e0f0;
            border: 1px solid #3a3a55;
            padding: 12px 28px;
            font-size: 1rem;
            font-weight: 500;
            border-radius: 8px;
            cursor: pointer;
            transition: all 0.2s ease;
            letter-spacing: 0.5px;
            min-width: 100px;
        }

        button:hover {
            background: #3a3a55;
            transform: translateY(-2px);
            box-shadow: 0 6px 12px rgba(0, 0, 0, 0.3);
        }

        button:active {
            transform: translateY(0);
        }

        #sort {
            background: #2d6a4f;
            border-color: #40916c;
        }

        #sort:hover {
            background: #40916c;
        }

        #shuffle {
            background: #5a4a3a;
            border-color: #7a6a5a;
        }

        #shuffle:hover {
            background: #7a6a5a;
        }

        #reset {
            background: #4a2a3a;
            border-color: #6a4a5a;
        }

        #reset:hover {
            background: #6a4a5a;
        }

        #bars {
            display: flex;
            align-items: flex-end;
            justify-content: center;
            gap: 3px;
            height: 55vh;
            min-height: 250px;
            background: #12121e;
            padding: 15px 10px;
            border-radius: 12px;
            border: 1px solid #2a2a40;
            margin-top: 10px;
        }

        .bar {
            background: linear-gradient(to top, #4facfe, #00f2fe);
            width: 100%;
            max-width: 30px;
            min-width: 4px;
            border-radius: 3px 3px 0 0;
            transition: height 0.08s ease, background 0.1s ease;
            flex-shrink: 1;
        }

        .bar.comparing {
            background: linear-gradient(to top, #ff6b6b, #ee5a24);
        }

        .bar.sorted {
            background: linear-gradient(to top, #2ecc71, #27ae60);
        }

        @media (max-width: 600px) {
            #app {
                padding: 20px 15px;
            }
            h1 {
                font-size: 1.4rem;
            }
            button {
                padding: 10px 16px;
                font-size: 0.9rem;
                min-width: 80px;
            }
            #bars {
                height: 45vh;
                min-height: 200px;
            }
        }
    </style>
</head>
<body>
    <div id="app">
        <h1>✦ Sorting Visualizer</h1>
        <div id="controls">
            <button id="sort">▶ Sort</button>
            <button id="shuffle">⟳ Shuffle</button>
            <button id="reset">↺ Reset</button>
        </div>
        <div id="bars"></div>
    </div>

    <script>
        // --- Core State ---
        let array = [];
        let sortGenerator = null;
        let sortInterval = null;

        // --- Utility / Helpers ---
        function generateRandomArray(size = 30) {
            const arr = [];
            for (let i = 0; i < size; i++) {
                arr.push(Math.floor(Math.random() * 90) + 10); // values 10-99
            }
            return arr;
        }

        // --- Sorting Algorithm (Bubble Sort as a Generator) ---
        // Yields after each comparison/swap, providing the indices being compared.
        function* bubbleSortGenerator(arr) {
            const n = arr.length;
            let swapped = false;
            for (let i = 0; i < n - 1; i++) {
                for (let j = 0; j < n - i - 1; j++) {
                    // Perform comparison (and swap if needed)
                    if (arr[j] > arr[j + 1]) {
                        // Swap
                        const temp = arr[j];
                        arr[j] = arr[j + 1];
                        arr[j + 1] = temp;
                        swapped = true;
                    }
                    // Yield indices being compared/swapped for highlighting
                    yield [j, j + 1];
                }
                // Optimization: if no swaps, array is sorted
                if (!swapped) {
                    break;
                }
                swapped = false;
            }
        }

        // --- Rendering ---
        function redraw(highlightIdx1 = -1, highlightIdx2 = -1) {
            const container = document.getElementById('bars');
            container.innerHTML = '';
            const maxVal = Math.max(...array, 1);
            const n = array.length;

            array.forEach((val, idx) => {
                const bar = document.createElement('div');
                bar.className = 'bar';
                // Highlight the two bars currently being compared
                if (idx === highlightIdx1 || idx === highlightIdx2) {
                    bar.classList.add('comparing');
                }
                // Style the bar height proportional to its value
                const heightPercent = (val / maxVal) * 100;
                bar.style.height = `${heightPercent}%`;
                // Add a data attribute for debugging, if needed
                bar.dataset.value = val;
                container.appendChild(bar);
            });
        }

        // --- Exposed API (window.viz) ---
        window.viz = {
            // Returns a copy of the current array
            array() {
                return [...array];
            },

            // Sets the internal array (copy) and redraws. Cancels any ongoing sort.
            setArray(a) {
                // Stop any ongoing sort animation
                if (sortInterval) {
                    clearInterval(sortInterval);
                    sortInterval = null;
                }
                sortGenerator = null;
                array = [...a];
                redraw();
            },

            // Advances the sort by exactly one step (one iteration of the inner loop).
            // Returns true if the array is fully sorted, false otherwise.
            sortStep() {
                // If already sorted, clean up and return true
                if (this.sorted()) {
                    sortGenerator = null;
                    if (sortInterval) {
                        clearInterval(sortInterval);
                        sortInterval = null;
                    }
                    redraw();
                    return true;
                }

                // If no generator is running, create a new one
                if (!sortGenerator) {
                    sortGenerator = bubbleSortGenerator(array);
                }

                // Advance the generator by one step
                const { value, done } = sortGenerator.next();

                // If the generator says it's done, check if sorted and clean up
                if (done) {
                    sortGenerator = null;
                    if (sortInterval) {
                        clearInterval(sortInterval);
                        sortInterval = null;
                    }
                    redraw();
                    return true;
                }

                // value is [index1, index2] of the comparison just made
                if (value) {
                    redraw(value[0], value[1]);
                } else {
                    redraw();
                }

                // Check if the array is fully sorted after this step
                if (this.sorted()) {
                    sortGenerator = null;
                    if (sortInterval) {
                        clearInterval(sortInterval);
                        sortInterval = null;
                    }
                    redraw();
                    return true;
                }

                return false;
            },

            // Checks if the current array is sorted in ascending order
            sorted() {
                for (let i = 0; i < array.length - 1; i++) {
                    if (array[i] > array[i + 1]) {
                        return false;
                    }
                }
                return true;
            }
        };

        // --- Button Event Handlers ---
        function handleShuffle() {
            // Stop any ongoing sort
            if (sortInterval) {
                clearInterval(sortInterval);
                sortInterval = null;
            }
            sortGenerator = null;
            const newArray = generateRandomArray(30);
            window.viz.setArray(newArray);
        }

        function handleReset() {
            handleShuffle(); // Reset just shuffles back to a random state
        }

        function handleSort() {
            // If already sorting, do nothing
            if (sortInterval) {
                return;
            }

            // If already sorted, shuffle first to demonstrate sorting
            if (window.viz.sorted()) {
                handleShuffle();
            }

            // Start interval to drive the sort
            sortInterval = setInterval(() => {
                const done = window.viz.sortStep();
                if (done) {
                    clearInterval(sortInterval);
                    sortInterval = null;
                    // Mark all bars as sorted (visual feedback)
                    document.querySelectorAll('.bar').forEach(bar => {
                        bar.classList.remove('comparing');
                        bar.classList.add('sorted');
                    });
                }
            }, 30); // 30ms = smooth ~33 fps animation
        }

        // --- Initialization ---
        document.addEventListener('DOMContentLoaded', () => {
            // Generate initial array
            const initialArray = generateRandomArray(30);
            window.viz.setArray(initialArray);

            // Bind buttons
            document.getElementById('sort').addEventListener('click', handleSort);
            document.getElementById('shuffle').addEventListener('click', handleShuffle);
            document.getElementById('reset').addEventListener('click', handleReset);
        });

        // (Optional) Expose helpers for debugging, but not required.
        console.log('Sorting Visualizer Ready!');
        console.log('API: window.viz.array(), .setArray(a), .sortStep(), .sorted()');
    </script>
</body>
</html>
